import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void layernorm_kernel(
    const T* __restrict__ X,
    const T* __restrict__ G,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int64_t N,
    float eps)
{
    int64_t b = blockIdx.x;
    const T* x_row = X + b * N;
    T* y_row = Y + b * N;
    int tid = threadIdx.x;
    int nthreads = blockDim.x;
    int64_t N4 = N / 4;
    int64_t rem_start = N4 * 4;
    const float4* x_row4 = reinterpret_cast<const float4*>(x_row);
    float4* y_row4 = reinterpret_cast<float4*>(y_row);
    const float4* g_row4 = reinterpret_cast<const float4*>(G);
    const float4* b_row4 = reinterpret_cast<const float4*>(B);
    float sum = 0.0f, sumsq = 0.0f;
    for (int64_t i = tid; i < N4; i += nthreads) {
        float4 v4 = x_row4[i];
        sum   += v4.x + v4.y + v4.z + v4.w;
        sumsq += v4.x * v4.x + v4.y * v4.y + v4.z * v4.z + v4.w * v4.w;
    }
    for (int64_t i = rem_start + tid; i < N; i += nthreads) {
        float v = static_cast<float>(x_row[i]);
        sum += v;
        sumsq += v * v;
    }
    // Warp-level reduction
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        sum   += __shfl_down_sync(0xffffffffu, sum, offset);
        sumsq += __shfl_down_sync(0xffffffffu, sumsq, offset);
    }
    __shared__ float warp_sum[32];
    __shared__ float warp_sumsq[32];
    int lane = tid & 31;
    int wid  = tid >> 5;
    if (lane == 0) {
        warp_sum[wid]   = sum;
        warp_sumsq[wid] = sumsq;
    }
    __syncthreads();
    int num_warps = (nthreads + 31) / 32;
    if (wid == 0) {
        float s  = (lane < num_warps) ? warp_sum[lane]   : 0.0f;
        float sq = (lane < num_warps) ? warp_sumsq[lane] : 0.0f;
        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            s  += __shfl_down_sync(0xffffffffu, s, offset);
            sq += __shfl_down_sync(0xffffffffu, sq, offset);
        }
        if (lane == 0) {
            warp_sum[0]   = s;
            warp_sumsq[0] = sq;
        }
    }
    __syncthreads();
    float mean = warp_sum[0] / static_cast<float>(N);
    float var  = warp_sumsq[0] / static_cast<float>(N) - mean * mean;
    float inv_std = rsqrtf(var + eps);
    for (int64_t i = tid; i < N4; i += nthreads) {
        float4 v4 = x_row4[i];
        float4 gv = g_row4[i];
        float4 bv = b_row4[i];
        float4 out;
        out.x = (v4.x - mean) * inv_std * gv.x + bv.x;
        out.y = (v4.y - mean) * inv_std * gv.y + bv.y;
        out.z = (v4.z - mean) * inv_std * gv.z + bv.z;
        out.w = (v4.w - mean) * inv_std * gv.w + bv.w;
        y_row4[i] = out;
    }
    for (int64_t i = rem_start + tid; i < N; i += nthreads) {
        float v = static_cast<float>(x_row[i]);
        float norm = (v - mean) * inv_std;
        float g = static_cast<float>(G[i]);
        float bb = static_cast<float>(B[i]);
        y_row[i] = static_cast<T>(norm * g + bb);
    }
}

torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(weight.is_cuda(), "weight must be CUDA");
    TORCH_CHECK(bias.is_cuda(), "bias must be CUDA");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    TORCH_CHECK(weight.scalar_type() == at::kFloat, "weight must be float32");
    TORCH_CHECK(bias.scalar_type() == at::kFloat, "bias must be float32");

    auto x_c = x.contiguous();
    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    int64_t N = w_c.numel();
    TORCH_CHECK(x_c.numel() % N == 0, "x numel must be divisible by normalized_shape numel");
    int64_t batch = x_c.numel() / N;

    auto y = torch::empty_like(x_c);

    int threads = 1024;
    dim3 grid((unsigned)batch);
    dim3 block((unsigned)threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    layernorm_kernel<float><<<grid, block, 0, stream>>>(
        x_c.data_ptr<float>(),
        w_c.data_ptr<float>(),
        b_c.data_ptr<float>(),
        y.data_ptr<float>(),
        N,
        static_cast<float>(eps)
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "layernorm_kernel launch failed: ", cudaGetErrorString(err));

    return y;
}
"""

layernorm_ext = load_inline(
    name="cute_layernorm_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["layernorm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUDA kernel using CuTe tensors.
    """
    def __init__(self, normalized_shape: tuple):
        super(ModelNew, self).__init__()
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(*self.normalized_shape))
        self.bias = nn.Parameter(torch.zeros(*self.normalized_shape))
        self._ext = layernorm_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.layernorm_forward(
            x.contiguous(),
            self.weight,
            self.bias,
            self.eps,
        )

