    auto w_c = weight.contiguous();
    auto b_c = bias.contiguous();

    int64_t N = w_c.numel();
    TORCH_CHECK(x_c.numel() % N == 0, "x numel must be divisible by normalized_shape numel");
    int64_t batch = x_c.numel() / N;

    auto y = torch::empty_like(x_c);

    int threads = 1024;
    dim3 grid((unsigned)batch);
